    <script>
        document.addEventListener('DOMContentLoaded', function() {
            // Payment method selection
            const paymentMethods = document.querySelectorAll('.payment-method');
            paymentMethods.forEach(method => {
                method.addEventListener('click', function() {
                    paymentMethods.forEach(m => m.classList.remove('selected'));
                    this.classList.add('selected');
                });
            });

            // Form validation
            const completePaymentBtn = document.querySelector('.btn:not(.btn-secondary)');
            completePaymentBtn.addEventListener('click', function(e) {
                e.preventDefault();

                // Simple validation
                const inputs = document.querySelectorAll('input');
                let isValid = true;

                inputs.forEach(input => {
                    if (!input.value) {
                        isValid = false;
                        input.style.borderColor = 'red';
                    } else {
                        input.style.borderColor = '';
                    }
                });

                if (isValid) {
                    // Simulate payment processing
                    this.textContent = 'Processing...';
                    this.disabled = true;

                    setTimeout(() => {
                        alert('Payment successful! Confirmation email sent to john@example.com');
                        this.textContent = 'Payment Complete';
                    }, 2000);
                } else {
                    alert('Please fill in all required fields');
                }
            });
        });
    </script>
</body>
</html>
```
- Professional law firm checkout with modern design and subtle hover animations
- Fully responsive layout that adapts to all device sizes
- Interactive payment selection and form validation with smooth transitions

